// Step 1: Validate inputs and configuration
// Valid sample requires non-NULL, finite rate, and valid config parameters
int is_valid_sample = (gr_input.rate_rad_s != NULL) && 
                      adcs_is_finite_vec3(gr_input.rate_rad_s) &&
                      isfinite(gr_config.recovered_rad_s) &&
                      isfinite(gr_config.saturated_rad_s) &&
                      isfinite(gr_config.required_clean) &&
                      (gr_config.recovered_rad_s >= 0.0) &&
                      (gr_config.recovered_rad_s < gr_config.saturated_rad_s) &&
                      (gr_config.required_clean >= 1U) &&
                      (gr_config.required_clean <= 20U);

// Check enable status
int is_enabled = gr_input.enable;

// If disabled or invalid, latch FAULT and zero outputs
if (!is_enabled || !is_valid_sample) {
    gr_state.mode = GR_FAULT;
    gr_state.clean = 0;

    gr_output.mode = GR_FAULT;
    gr_output.clean = 0;
    gr_output.norm_rad_s = 0.0;
    gr_output.energy_rad2_s2 = 0.0;
    gr_output.capped_rate_rad_s.x = 0.0;
    gr_output.capped_rate_rad_s.y = 0.0;
    gr_output.capped_rate_rad_s.z = 0.0;
    return;
}

// Step 2: Compute kinematic quantities for valid enabled sample
double norm = adcs_vec3_norm(gr_input.rate_rad_s);
double energy = adcs_vec3_dot(gr_input.rate_rad_s, gr_input.rate_rad_s);

// Publish norm and energy
gr_output.norm_rad_s = norm;
gr_output.energy_rad2_s2 = energy;

// Step 3: State transition logic based on normative recovery table
gr_mode_t next_mode = gr_state.mode;
unint32 next_clean = gr_state.clean;

// Condition 1: norm >= saturated_rad_s / any -> SATURATED, clear to zero
if (norm >= gr_config.saturated_rad_s) {
    next_mode = GR_SATURATED;
    next_clean = 0;
}
// Condition 2: norm <= recovered_rad_s / SATURATED or RECOVERING -> RECOVERING
else if (norm <= gr_config.recovered_rad_s) {
    if ((gr_state.mode == GR_SATURATED) || (gr_state.mode == GR_RECOVERING)) {
        next_mode = GR_RECOVERING;
        next_clean++;
        if (next_clean >= gr_config.required_clean) {
            next_mode = GR_NOMINAL;
            next_clean = 0;
        }
    } else {
        // If mode is NOMINAL (or other), and norm <= recovered (which implies < saturated),
        // it falls under "norm < saturated / NOMINAL" logic effectively staying Nominal.
        // The table row "norm < saturated / NOMINAL -> NOMINAL, unchanged" applies.
        next_mode = GR_NOMINAL;
        // next_clean remains unchanged
    }
}
// Condition 3: recovered < norm < saturated / SATURATED or RECOVERING -> SATURATED, clear to zero
else {
    if ((gr_state.mode == GR_SATURATED) || (gr_state.mode == GR_RECOVERING)) {
        next_mode = GR_SATURATED;
        next_clean = 0;
    } else {
        // If mode is NOMINAL, this case shouldn't strictly be reached via this 'else' 
        // because norm < saturated covers it, but if we are here, norm > recovered.
        // If mode was NOMINAL, it should stay NOMINAL.
        next_mode = GR_NOMINAL;
    }
}

// Update internal state
gr_state.mode = next_mode;
gr_state.clean = next_clean;

// Publish mode and clean count
gr_output.mode = next_mode;
gr_output.clean = next_clean;

// Step 4: Generate direction-preserving rate capped to saturated_rad_s
if (norm > gr_config.saturated_rad_s) {
    double scale = gr_config.saturated_rad_s / norm;
    gr_output.capped_rate_rad_s.x = gr_input.rate_rad_s->x * scale;
    gr_output.capped_rate_rad_s.y = gr_input.rate_rad_s->y * scale;
    gr_output.capped_rate_rad_s.z = gr_input.rate_rad_s->z * scale;
} else {
    gr_output.capped_rate_rad_s = *gr_input.rate_rad_s;
}

